import json,subprocess,sys
def gh(*args):
 return json.loads(subprocess.check_output(["gh",*args],text=True))
repo="unbrowse-ai/unbrowse-core"
root="repos/"+repo
sha=gh("api",root+"/branches/staging")["commit"]["sha"]
runs=gh("api","-X","GET",root+"/actions/workflows/qa.yml/runs","-f","head_sha="+sha,"-f","branch=staging","-f","per_page=100")["workflow_runs"]
row=next((r for r in runs if r["event"] in ("push","workflow_dispatch","schedule")),None)
if row is None: sys.exit("No QA workflow on "+sha)
jobs=gh("api","--paginate","--slurp",f"{root}/actions/runs/{row['id']}/jobs?per_page=100")
jobs={j["name"]:j["conclusion"] for page in jobs for j in page["jobs"]}
required=("Build the node once","MCP check (no model)","Claude QA (1)","Claude QA (2)","Claude QA (3)","Claude QA (4)","Gate bank / Gate bank (slice)","QA report")
print(sha,row["html_url"],row["status"],row["conclusion"])
for name in required: print(name,jobs.get(name) or "missing")
if gh("api",root+"/branches/staging")["commit"]["sha"]!=sha: sys.exit("staging moved during verification")
if row["conclusion"]!="success" or any(jobs.get(name)!="success" for name in required): sys.exit(1)
print("STAGING_QA_GREEN")
